func loadAgent(workers int) (*ebpfPolicy, error) {
	if err := ensureRlimit(); err != nil {
		return nil, err
	}
	pinDir := pinDirectory()
	if err := ensurePinDirectory(pinDir); err != nil {
		return nil, fmt.Errorf("ensure pin directory: %w", err)
	}
	var objs ebpfutil.AgentSelectorObjects
	opts := &ebpf.CollectionOptions{
		Maps: ebpf.MapOptions{PinPath: pinDir},
	}
	if err := ebpfutil.LoadAgentSelectorObjects(&objs, opts); err != nil {
		return nil, fmt.Errorf("load agent objects: %w", err)
	}

	if workers < 0 {
		objs.Close()
		return nil, ErrInvalidConfig("workers must be non-negative")
	}

	var key uint32 = 0
	state := ebpfutil.AgentSelectorAgentState{
		Active: uint32(workers),
	}
	if objs.PebbleAgentState != nil {
		if err := objs.PebbleAgentState.Update(&key, &state, ebpf.UpdateAny); err != nil {
			objs.Close()
			return nil, fmt.Errorf("configure agent state: %w", err)
		}
	}

	return &ebpfPolicy{
		name:    "agent",
		program: objs.AgentUdpSelector,
		close:   objs.Close,
	}, nil
}

type ebpfPolicy struct {
	name    string
	program *ebpf.Program
	close   func() error
}

const defaultPinBase = "/sys/fs/bpf"

func pinDirectory() string {
	if path := os.Getenv("BPF_PIN_PATH"); path != "" {
		return path
	}
	if base := os.Getenv("BPF_PIN_BASE"); base != "" {
		return base
	}
	return defaultPinBase
}

func ensurePinDirectory(path string) error {
	return os.MkdirAll(path, 0o755)
}

func ensureRlimit() error {
	if err := rlimit.RemoveMemlock(); err != nil {
		return fmt.Errorf("adjust memlock: %w", err)
	}
	return nil
}

func loadRoundRobin(workers int) (*ebpfPolicy, error) {
	if err := ensureRlimit(); err != nil {
		return nil, err
	}
	pinDir := pinDirectory()
	if err := ensurePinDirectory(pinDir); err != nil {
		return nil, fmt.Errorf("ensure pin directory: %w", err)
	}
	var objs ebpfutil.RrSelectorObjects
	opts := &ebpf.CollectionOptions{
		Maps: ebpf.MapOptions{PinPath: pinDir},
	}
	if err := ebpfutil.LoadRrSelectorObjects(&objs, opts); err != nil {
		return nil, fmt.Errorf("load round robin objects: %w", err)
	}

	var key uint32 = 0
	state := ebpfutil.RrSelectorRrState{}
	if err := objs.PebbleRrState.Lookup(&key, &state); err != nil {
		state.Active = uint32(workers)
		state.Counter = 0
	} else {
		state.Active = uint32(workers)
	}
	if err := objs.PebbleRrState.Update(&key, &state, ebpf.UpdateAny); err != nil {
		objs.Close()
		return nil, fmt.Errorf("configure round robin state: %w", err)
	}

	return &ebpfPolicy{
		name:    "round_robin",
		program: objs.RrUdpSelector,
		close:   objs.Close,
	}, nil
}

func loadEBPF(policy string, workers int) (*ebpfPolicy, error) {
	switch policy {
	case "default", "":
		return &ebpfPolicy{name: "default"}, nil
	case "round_robin":
		return loadRoundRobin(workers)
	case "agent":
		return loadAgent(workers)
	case "scan_split":
		return loadScanSplit(workers)
	case "hash":
		return loadHash(workers)
	default:
		return nil, ErrInvalidConfig(fmt.Sprintf("unknown policy %q", policy))
	}
}

